<script setup lang="ts">defineProps<{rows:number;cols:number;errors:number;saved:boolean;draftStatus:'saved'|'saving'|'draft';lastAutoSaved:string;zoom:number}>();const emit=defineEmits<{zoom:[value:number]}>();</script>
<template><footer class="status-bar"><span>{{ rows }} 行 × {{ cols }} 列</span><span :class="{statusError:errors}">{{ errors ? `${errors} 个错误` : '数据正常' }}</span><span>{{ saved?'已保存':'有未保存更改' }}</span><span v-if="draftStatus==='saving'">自动保存中…</span><span v-else-if="lastAutoSaved">草稿 {{lastAutoSaved}}</span><span v-else>草稿未生成</span><span class="privacy-note">仅在本机处理</span><div class="zoom-control"><button @click="emit('zoom',Math.max(50,zoom-10))">−</button><input type="range" min="50" max="150" step="10" :value="zoom" @input="emit('zoom',Number(($event.target as HTMLInputElement).value))"><button @click="emit('zoom',Math.min(150,zoom+10))">＋</button><strong>{{ zoom }}%</strong></div></footer></template>
